#include <assert.h>
#include <cmath>
#include "../main/src/main_policy.h"
static Proto::Frame result(uint16_t job,uint8_t part,float value){uint8_t p[24];uint8_t n=part?16:24;for(uint8_t i=0;i<n/4;i++)Proto::putFloat(p+4*i,value);Proto::Frame f;Proto::make(f,Proto::RESULT,job,part,p,n);return f;}
int main(){uint8_t state[12]={0};Proto::put32(state,11);Proto::put16(state+10,55);Proto::Frame ack;Proto::make(ack,Proto::ACK,55,0,state,12);assert(MainPolicy::appliedAck(ack,11,55));assert(!MainPolicy::appliedAck(ack,11,56));assert(!MainPolicy::appliedAck(ack,12,55));state[9]=1;Proto::make(ack,Proto::ACK,55,0,state,12);assert(!MainPolicy::appliedAck(ack,11,55));assert(MainPolicy::exactStop("  StOp!?  ",10));assert(!MainPolicy::exactStop("stop horn",9));assert(!MainPolicy::exactStop("stoplight",9));MainPolicy::Scores s;s.reset(37,8);auto a=result(37,0,1.25f),b=result(37,1,1.25f);assert(!s.accept(0,a,9));assert(s.complete==0);assert(s.accept(0,a,8));assert(!s.accept(0,a,8));assert(s.accept(0,b,8));assert(s.complete==1);assert(s.accept(1,b,8));assert(s.accept(1,a,8));assert(s.complete==3);for(int i=0;i<10;i++)assert(std::fabs(s.z[i]-(rdf(IntentMain::C+i)+2.5f))<1e-6f);s.reset(38,10);assert(!s.accept(1,a,10));auto nan=result(38,0,NAN);assert(!s.accept(0,nan,10));assert(!s.masks[0]);auto bad=result(38,0,2);bad.bytes[31]^=1;assert(!s.accept(0,bad,10));Intent::Input in;Intent::parse("go forward",10,in);assert(in.reason==Intent::OK);assert(in.count==2);Intent::parse("flibbertigibbet",15,in);assert(in.reason==Intent::OOV);}
